        res[rc++] = b64[ (0x3&bin[byteNo])<<4 ] ;
        res[rc++] = '=';
        res[rc++] = '=';
    }
    else if( pad==1 )
    {
        res[rc++]  = b64[ bin[byteNo] >> 2 ] ;
        res[rc++]  = b64[ ((0x3&bin[byteNo])<<4)   +   (bin[byteNo+1] >> 4) ] ;
        res[rc++]  = b64[ (0x0f&bin[byteNo+1])<<2 ] ;
        res[rc++] = '=';
    }

    res[rc]=0; // NULL TERMINATOR! ;)
    return res ;
}

